#define BINARY_SEARCH_TREE_H

#include <memory>
#include <stack>

namespace binary_search_tree {

template <typename T>
class binary_tree {
public:
    explicit binary_tree(const T& data) : data_(data) {}

    void insert(const T& value) {
        if (value < data_) {
            if (left_) {
                left_->insert(value);
            } else {
                left_.reset(new binary_tree<T>(value));
            }
        } else {
            if (right_) {
                right_->insert(value);
            } else {
                right_.reset(new binary_tree<T>(value));
            }
        }
    }

    const T& data() const { return data_; }

    const std::unique_ptr<binary_tree<T>>& left() const { return left_; }
    const std::unique_ptr<binary_tree<T>>& right() const { return right_; }

    class iterator {
    public:
        iterator() = default;
        explicit iterator(binary_tree<T>* root) { push_left(root); }

        const T& operator*() const { return stack_.top()->data_; }

        iterator& operator++() {
            binary_tree<T>* node = stack_.top();
            stack_.pop();
            push_left(node->right_.get());
            return *this;
        }

        bool operator==(const iterator& other) const {
            return stack_.empty() && other.stack_.empty();
        }

        bool operator!=(const iterator& other) const { return !(*this == other); }

    private:
        void push_left(binary_tree<T>* node) {
            while (node != nullptr) {
                stack_.push(node);
                node = node->left_.get();
            }
        }

        std::stack<binary_tree<T>*> stack_;
    };

    iterator begin() { return iterator(this); }
    iterator end() { return iterator(); }

private:
    T data_;
    std::unique_ptr<binary_tree<T>> left_;
    std::unique_ptr<binary_tree<T>> right_;
};

}  // namespace binary_search_tree

#endif // BINARY_SEARCH_TREE_H
